<?php
namespace App\Domain\Workplan\Models; use App\Models\Concerns\HasMdaScope; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class WorkplanIndicatorProgress extends Model { use HasMdaScope; protected $table='workplan_indicator_progresses'; protected $fillable=['mda_id','workplan_progress_report_id','workplan_indicator_id','target_value_snapshot','actual_value','achievement_ratio','verification_note']; protected function casts():array{return ['target_value_snapshot'=>'decimal:4','actual_value'=>'decimal:4','achievement_ratio'=>'decimal:6'];} public function report():BelongsTo{return $this->belongsTo(WorkplanProgressReport::class,'workplan_progress_report_id');} public function indicator():BelongsTo{return $this->belongsTo(WorkplanIndicator::class,'workplan_indicator_id');} }
